s+='<div class="compare"><img src="/art/studies/ground-085/main.png" alt="085 baseline"><img id="after" class="after" src="'+A+'main.png" alt="086 actual deposits"></div><label for="slider">085 before ← drag → 086 after</label><input id="slider" type="range" min="0" max="100" value="50" oninput="document.getElementById(\'after\').style.clipPath=\'inset(0 0 0 \'+this.value+\'%)\'"><p><a href="'+A+'main.png">Full candidate</a></p>'
